import {projects,extras,initial,isPodcast,isEditing,isPhoto,priceLines,total,scopeText,narrative,reviewItems,change,restore} from './domain.mjs';
const $=selector=>document.querySelector(selector);
const money=value=>`N$ ${value.toLocaleString('en-NA')}`;
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
const DRAFT='vh-configurator-v2';
const catalogue=[
 {id:'event',title:'Event recap',service:'Video',tag:'Events',image:'events',subtitle:'Keep the energy. Relive the night.',included:['Event coverage','Highlight edit','Colour & sound'],icon:'clapperboard'},
 {id:'podcast',title:'Podcast',service:'Video',tag:'Conversations',image:'podcast',subtitle:'Good conversations. Beautifully captured.',included:['Camera setup','Clear audio','Episode edit'],icon:'mic'},
 {id:'reel',title:'Social reel',service:'Video',tag:'Social content',image:'camera',subtitle:'A small film. A lasting impression.',included:['Shoot time','Vertical edit','Colour & sound'],icon:'smartphone'},
 {id:'portrait',title:'Portraits',service:'Photo',tag:'Photography',image:'portrait',subtitle:'For the people behind the story.',included:['Photo session','Image selection','Retouching'],icon:'camera'},
 {id:'music',title:'Music video',service:'Video',tag:'Artists',image:'events',subtitle:'Give your sound a visual world.',included:['Shoot planning','Filming','Main edit'],icon:'music-2'},
 {id:'brand',title:'Brand content',service:'Photo + video',tag:'For your brand',image:'camera',subtitle:'Photography and film, working together.',included:['Photo + video','Shoot planning','Post-production'],icon:'layers'},
 {id:'edit',title:'Podcast edit',service:'Editing',tag:'Post-production',image:'podcast',subtitle:'Your footage, brought together.',included:['Footage review','Main edit','Sound mix'],icon:'scissors'},
 {id:'interview',title:'Interview',service:'Video',tag:'People & stories',image:'portrait',subtitle:'Let your story do the talking.',included:['Camera setup','Interview audio','Main edit'],icon:'messages-square'},
 {id:'commercial',title:'Commercial',service:'Video',tag:'Campaigns',image:'camera',subtitle:'Build something with purpose.',included:['Scope review','Production plan','Main edit'],icon:'film'},
];
for(const [service,names] of Object.entries(projects)){for(const title of names){if(!catalogue.some(item=>item.title===title&&item.service===service))catalogue.push({id:`${service}-${title}`.toLowerCase().replace(/[^a-z0-9]+/g,'-'),title,service,tag:service==='Photo'?'Photography':service==='Editing'?'Post-production':'Production',image:service==='Photo'?'portrait':service==='Editing'?'camera':'events',subtitle:'Built around your brief.',included:['Scope review','Flexible setup','Post-production'],icon:service==='Photo'?'camera':service==='Editing'?'scissors':'video'})}}
let state=initial(),view='explore',category='All',query='',selectedId='',summaryOpen=false,priceChange='',savedIds=[],detailsOpen=false;
try{const stored=JSON.parse(localStorage.getItem(DRAFT));if(stored&&Date.now()-stored.savedAt<7*86400000)state=restore(stored.state);const saved=JSON.parse(localStorage.getItem('vh-saved'));if(Array.isArray(saved))savedIds=saved.filter(id=>catalogue.some(item=>item.id===id))}catch{}
if(state.project&&state.section==='project')state.section='shoot';
function persist(){try{localStorage.setItem(DRAFT,JSON.stringify({savedAt:Date.now(),state}));localStorage.setItem('vh-saved',JSON.stringify(savedIds))}catch{/* Preview remains usable without device storage. */}}
function selectedItem(){return (view==='detail'?catalogue.find(item=>item.id===selectedId):catalogue.find(item=>item.title===state.project))||catalogue[0]}
function choose(key,value){const before=total(state);state=change(state,key,value);const difference=total(state)-before;priceChange=difference?`${difference>0?'+':'−'}${money(Math.abs(difference))}`:'';render();if(state.project)$('#price-announcement').textContent=`${scopeText(state)}. Demo estimate ${money(total(state))}.`}
function header(){
 const isHome=['explore','saved','studio'].includes(view);
 if(isHome)return `<div class="home-header"><div class="wordmark">vision<span>haus</span><span class="brand-dot"></span></div><div class="header-actions"><span class="preview-pill">UI Preview</span><button class="icon-button" data-view="studio" aria-label="About VisionHaus">${icon('circle-user-round')}</button></div></div>`;
 return `<div class="screen-header"><button class="icon-button" id="back" aria-label="Go back">${icon('arrow-left')}</button><span>${view==='detail'?'Your next production':state.complete?'Your plan':'Build your shoot'}</span><button class="icon-button" id="favorite" aria-label="${savedIds.includes(selectedItem().id)?'Remove from saved':'Save this service'}" aria-pressed="${savedIds.includes(selectedItem().id)}">${icon('heart',savedIds.includes(selectedItem().id)?'filled':'')}</button></div>`;
}
function tabBar(){const tabs=[['explore','house','Explore'],['plan','clipboard-list','My plan'],['saved','heart','Saved'],['studio','circle-user-round','Studio']];return tabs.map(([id,ic,label])=>`<button data-view="${id}" ${view===id||id==='plan'&&view==='detail'?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='plan'&&state.project?'<b class="tab-dot"></b>':''}</button>`).join('')}
function photoCard(item,compact=false){return `<article class="photo-card ${compact?'compact':''}"><button class="photo-main" data-detail="${item.id}" aria-label="Explore ${item.title}"><img src="/assets/${item.image}.jpg" alt="${item.tag} production inspiration" ${compact?'loading="lazy"':''}><span class="image-shade"></span><span class="photo-tag">${icon(item.icon)}${item.tag}</span><span class="photo-caption"><span><small>VISIONHAUS MEDIA</small><strong>${item.title}</strong></span><span class="round-arrow">${icon('arrow-up-right')}</span></span></button><button class="save-button ${savedIds.includes(item.id)?'is-saved':''}" data-save="${item.id}" aria-label="${savedIds.includes(item.id)?'Unsave':'Save'} ${item.title}" aria-pressed="${savedIds.includes(item.id)}">${icon('heart')}</button></article>`}
function explore(){const filtered=catalogue.filter(item=>(category==='All'||item.service===category)&&`${item.title} ${item.tag}`.toLowerCase().includes(query.toLowerCase()));return `<section class="explore-page"><div class="greeting"><p>Made for your next idea</p><h1>What’s your next shoot?</h1></div><label class="search-field">${icon('search')}<input id="search" type="search" placeholder="Find a service" aria-label="Find a service" value="${escape(query)}"><span>${icon('sliders-horizontal')}</span></label><div class="category-strip" aria-label="Service categories">${[['All','grid-2x2','All'],['Video','video','Video'],['Photo','camera','Photo'],['Photo + video','layers','Both'],['Editing','scissors','Editing']].map(([value,ic,label])=>`<button data-category="${value}" aria-pressed="${category===value}" class="${category===value?'active':''}">${icon(ic)}${label}</button>`).join('')}</div><div class="section-title"><h2>${query?'Search results':category==='All'?'Find your starting point':category==='Photo'?'Photography':category}</h2><span>${filtered.length} services</span></div><div class="service-feed">${filtered.length?filtered.map((item,i)=>photoCard(item,i>1)).join(''):`<div class="empty-state">${icon('search')}<h2>No services found</h2><p>Try “podcast”, “reel” or “portrait”.</p><button class="secondary" id="clear-search">Clear search</button></div>`}</div><p class="image-credit">Service imagery is illustrative. Your production is made for you.</p></section>`}
function detail(){const item=selectedItem();return `<section class="detail-page"><div class="detail-image"><img src="/assets/${item.image}.jpg" alt="${item.tag} production inspiration"><span class="image-shade"></span><span class="detail-tag">${icon(item.icon)}${item.tag}</span></div><div class="detail-sheet"><div class="sheet-handle"></div><div class="detail-title"><h1>${item.title}</h1><span class="tiny-label">Made to fit you</span></div><p class="detail-subtitle">${item.subtitle}</p><div class="inclusion-chips">${item.included.map(text=>`<span>${icon('check')}${text}</span>`).join('')}</div><div class="section-title"><h2>Your shoot, your setup</h2></div><div class="detail-features"><div>${icon('sliders-horizontal')}<span>Flexible setup<small>Choose people, time & extras</small></span></div><div>${icon('receipt-text')}<span>Live estimate<small>See the price as you build</small></span></div><div>${icon('calendar-days')}<span>Your preferred date<small>Confirmed after quote review</small></span></div></div><p class="demo-note">Preview rates are illustrative.</p></div></section>`}
function segment(key,values,suffix=''){return `<div class="segments">${values.map(value=>`<button data-key="${key}" data-value="${value}" class="${state[key]===value?'selected':''}" aria-pressed="${state[key]===value}">${value}${suffix}</button>`).join('')}</div>`}
function counter(key,label,min,max,ic){return `<div class="setting-row"><span class="setting-label">${icon(ic)}${label}</span><div class="counter"><button data-key="${key}" data-value="${state[key]-1}" aria-label="Fewer ${label.toLowerCase()}" ${state[key]<=min?'disabled':''}>${icon('minus')}</button><output aria-label="${label}">${state[key]}</output><button data-key="${key}" data-value="${state[key]+1}" aria-label="More ${label.toLowerCase()}" ${state[key]>=max?'disabled':''}>${icon('plus')}</button></div></div>`}
function optionRow(key,value,title,sub,ic){return `<button class="option-row ${state[key]===value?'selected':''}" data-key="${key}" data-value="${escape(value)}" aria-pressed="${state[key]===value}"><span class="option-icon">${icon(ic)}</span><span class="option-label">${title}<small>${sub}</small></span><span class="radio-mark">${state[key]===value?icon('check'):''}</span></button>`}
function shoot(){return `<div class="page-heading"><h1>${isEditing(state)?'Your edit':'Make it your shoot'}</h1><p>${state.project} ${icon('dot')} ${state.location}</p></div>${isEditing(state)?`<div class="info-line">${icon('folder-video')}<span>Footage volume and edit length need review.</span></div>`:`${isPodcast(state)?`<section class="setting-group">${counter('people','People',1,4,'users')}${counter('episodes','Episodes',1,6,'clapperboard')}</section><div class="section-title"><h2>Choose your coverage</h2></div><section class="option-group">${optionRow('framing','Direct to camera','Solo focus','One camera view','user-round')}${optionRow('framing','Conversation','Conversation','Wide & close views','messages-square')}${optionRow('framing','Full coverage','Full coverage','Wide view & two close-ups','video')}</section><div class="setup-strip"><span>${icon('users')}${state.people} people</span><span>${icon('video')}${state.cameras} views</span><span>${icon('mic')}Clear audio</span></div>`:''}<div class="section-title"><h2>Time on location</h2></div>${segment('hours',[2,4,8],' hrs')}`}${dateLocation()}${!isEditing(state)&&!isPhoto(state)?`<details class="advanced" ${detailsOpen?'open':''}><summary>${icon('sliders-horizontal')}Camera details<span>Optional</span>${icon('chevron-down')}</summary><div class="advanced-body"><label class="field-label">Camera angles</label>${segment('cameras',[1,2,3])}<p class="field-note">Crew and lighting confirmed after review.</p></div></details>`:''}`}
function dateLocation(){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Windhoek',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());return `<section class="setting-group fields">${!isEditing(state)?`<label>${icon('map-pin')}<span>Location<select id="location">${['Windhoek','Swakopmund','Walvis Bay','Other / remote'].map(value=>`<option ${state.location===value?'selected':''}>${value}</option>`).join('')}</select></span></label>`:''}<label>${icon('calendar-days')}<span>${isEditing(state)?'Delivery date':'Preferred date'}<input type="date" id="date" value="${escape(state.date)}" min="${today}"><small>Optional · flexible dates welcome</small></span></label></section>`}
function delivery(){return `<div class="page-heading"><h1>The finishing touches</h1><p>${isPhoto(state)?'Photo post-production':'Your main edit'} is included.</p></div><section class="option-group">${extras.filter(extra=>!isPhoto(state)||extra.id==='rush').map(extra=>`<button class="option-row ${state.extras.includes(extra.id)?'selected':''}" data-extra="${extra.id}" aria-pressed="${state.extras.includes(extra.id)}"><span class="option-icon">${icon(extra.id==='clips'?'smartphone':extra.id==='captions'?'captions':'timer')}</span><span class="option-label">${extra.title}<small>${extra.description}</small><b>+${money(extra.price)}</b></span><span class="radio-mark">${state.extras.includes(extra.id)?icon('check'):''}</span></button>`).join('')}</section><div class="info-line">${icon('info')}<span>Final lengths and delivery dates are agreed in your quote.</span></div>`}
function receiptLines(){return `<div class="receipt-lines">${priceLines(state).map(line=>`<div><span>${line.label}</span><strong>${money(line.amount)}</strong></div>`).join('')}</div>`}
function review(){return `<div class="page-heading"><h1>Your plan is looking good</h1><p>A quick check before you finish.</p></div><div class="booking-ticket"><div class="ticket-top">${icon(selectedItem().icon)}<div><small>VISIONHAUS MEDIA</small><h2>${state.project}</h2></div><span class="status-label">Draft</span></div><p>${escape(narrative(state))}</p><div class="ticket-facts"><span>${icon('map-pin')}${isEditing(state)?'Remote edit':escape(state.location)}</span><span>${icon('calendar-days')}${state.date||'Date flexible'}</span></div><div class="ticket-total"><span>Demo estimate<small>Ex VAT · subject to review</small></span><strong>${money(total(state))}</strong></div></div><details class="price-details"><summary>Price breakdown ${icon('chevron-down')}</summary>${receiptLines()}</details><div class="review-needed"><span>${icon('circle-dashed')}Needs review</span><p>${reviewItems(state).join(' · ')}</p></div><form id="contact"><div class="section-title"><h2>Your details</h2></div><div class="contact-fields"><label>Your name<input id="name" autocomplete="name" placeholder="Name and surname" required maxlength="100" value="${escape(state.name)}"></label><label>Email address<input id="email" autocomplete="email" type="email" placeholder="you@example.com" required maxlength="150" value="${escape(state.email)}"></label></div></form><p class="demo-note">Demo only. Nothing is sent. Your brief stays on this device.</p>`}
function plan(){if(!state.project)return empty('clipboard-list','Your next shoot starts here','Choose a service to build your plan.','Explore services','explore');if(state.complete)return `<div class="completion"><span class="completion-icon">${icon('check')}</span><h1>Your demo plan is ready</h1><p>${escape(narrative(state))}</p><div class="booking-ticket"><div class="ticket-total"><span>Demo estimate<small>Nothing has been sent</small></span><strong>${money(total(state))}</strong></div></div><button class="primary" id="download">${icon('download')}Download brief</button><button class="secondary" id="edit-plan">Edit your plan</button></div>`;return `<div class="plan-layout"><div class="plan-main"><div class="plan-heading"><img src="/assets/${selectedItem().image}.jpg" alt=""><div><small>YOUR PRODUCTION</small><strong>${state.project}</strong></div><button class="icon-button" data-view="explore" aria-label="Choose another service">${icon('repeat-2')}</button></div><nav class="plan-sections" aria-label="Plan sections">${[['shoot','Setup'],['delivery','Extras'],['review','Review']].map(([id,label],i)=>`<button data-section="${id}" ${state.section===id?'aria-current="page"':''}><span>${i+1}</span>${label}</button>`).join('')}</nav><section id="task">${({shoot,delivery,review})[state.section==='project'?'shoot':state.section]()}</section></div><aside class="desktop-summary">${summaryContent()}<button class="primary" data-next>${nextLabel()}${icon('arrow-right')}</button></aside></div>`}
function summaryContent(){return `<div class="summary-heading"><span>Your production</span><span class="tiny-label">Demo</span></div><h2>${state.project}</h2><p class="summary-description">${escape(narrative(state))}</p><div class="summary-total"><span>Estimated total</span><strong>${money(total(state))}</strong><small>Ex VAT · illustrative pricing</small></div><div class="price-change" aria-hidden="true">${priceChange}</div><details class="price-details"><summary>Price breakdown ${icon('chevron-down')}</summary>${receiptLines()}</details><div class="review-needed"><span>${icon('circle-dashed')}Needs review</span><p>${reviewItems(state).join(' · ')}</p></div>`}
function saved(){const items=catalogue.filter(item=>savedIds.includes(item.id));return `<section class="explore-page"><div class="page-heading"><h1>Saved for later</h1><p>Your ideas, all in one place.</p></div>${items.length?`<div class="service-feed">${items.map(item=>photoCard(item)).join('')}</div>`:empty('heart','Keep your favourites close','Tap the heart on any service to save it.','Explore services','explore')}</section>`}
function empty(ic,title,text,button,target){return `<section class="empty-state">${icon(ic)}<h1>${title}</h1><p>${text}</p><button class="primary" data-view="${target}">${button}${icon('arrow-right')}</button></section>`}
function studio(){return `<section class="studio-page"><div class="studio-avatar">vh<span></span></div><h1>VisionHaus Media</h1><p>Film. Photography. Your next idea.</p><div class="studio-location">${icon('map-pin')}Windhoek, Namibia</div><section class="setting-group"><div class="studio-row">${icon('user-round')}<span>Guest experience<small>No client account needed</small></span></div><div class="studio-row">${icon('smartphone')}<span>App preview<small>Installable PWA in development</small></span></div><div class="studio-row">${icon('shield-check')}<span>Your draft stays here<small>Stored on this device for 7 days</small></span></div></section><button class="secondary" id="reset">${icon('rotate-ccw')}Clear draft & start again</button><p class="demo-note">UI prototype. Live bookings, email and Zoho are not connected.</p></section>`}
function nextLabel(){return state.section==='review'?'Save demo brief':state.section==='delivery'?'Review plan':'Choose extras'}
function controls(){
 if(view==='detail')return `<div class="action-dock detail-dock"><div><small>Built around your brief</small><strong>Let’s plan it</strong></div><button class="primary" id="build">Build my shoot${icon('arrow-right')}</button></div>`;
 if(view!=='plan'||!state.project||state.complete)return '';
 return `<div class="mobile-plan-controls"><details class="mobile-disclosure" ${summaryOpen?'open':''}><summary class="action-dock" id="summary-toggle" aria-label="Expand production estimate"><span class="summary-trigger"><span>${escape(scopeText(state))}</span><strong>${money(total(state))}${icon('chevron-up')}</strong><small>Ex VAT · demo estimate</small></span></summary><section class="mobile-summary" id="mobile-summary" aria-label="Production summary">${summaryContent()}</section></details><button class="primary dock-next" data-next>${state.section==='review'?'Save demo':'Continue'}${icon('arrow-right')}</button></div>`;
}
function render(){persist();$('#app-header').innerHTML=header();$('#app').innerHTML=({explore,saved,studio,detail,plan})[view]();$('#control-surface').innerHTML=controls();$('#tab-bar').innerHTML=tabBar();document.body.dataset.view=view;window.lucide.createIcons({attrs:{'stroke-width':1.7}});bind()}
function navigate(target){view=target;summaryOpen=false;render();scrollTo({top:0})}
function focusTask(){const h=$('#task h1')||$('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}scrollTo({top:0})}
function next(){if(state.section==='review'){if(!$('#contact').reportValidity()){summaryOpen=false;$('#control-surface').innerHTML=controls();window.lucide.createIcons();bindControls();return}state.complete=true}else state.section=state.section==='delivery'?'review':'delivery';summaryOpen=false;render();focusTask()}
function bindControls(){
 document.querySelectorAll('[data-next]').forEach(button=>button.onclick=next);
 if($('.mobile-disclosure'))$('.mobile-disclosure').ontoggle=event=>{if(event.target.isConnected)summaryOpen=event.target.open};
}
function toggleSaved(id){savedIds=savedIds.includes(id)?savedIds.filter(value=>value!==id):[...savedIds,id];render()}
function bind(){
 document.querySelectorAll('button[data-view]').forEach(button=>button.onclick=()=>navigate(button.dataset.view));
 document.querySelectorAll('[data-detail]').forEach(button=>button.onclick=()=>{selectedId=button.dataset.detail;navigate('detail')});
 document.querySelectorAll('[data-save]').forEach(button=>button.onclick=()=>toggleSaved(button.dataset.save));
 document.querySelectorAll('[data-category]').forEach(button=>button.onclick=()=>{category=button.dataset.category;render()});
 if($('#favorite'))$('#favorite').onclick=()=>toggleSaved(selectedItem().id);
 if($('#back'))$('#back').onclick=()=>navigate('explore');
 if($('#search'))$('#search').oninput=event=>{const start=event.target.selectionStart;query=event.target.value;render();$('#search').focus({preventScroll:true});if(start!==null)try{$('#search').setSelectionRange(start,start)}catch{}};
 if($('#clear-search'))$('#clear-search').onclick=()=>{query='';render()};
 if($('#build'))$('#build').onclick=()=>{const item=selectedItem();state=change(state,'service',item.service);state=change(state,'project',item.title);state.section='shoot';navigate('plan');focusTask()};
 document.querySelectorAll('[data-key]').forEach(button=>button.onclick=()=>{const key=button.dataset.key,label=button.getAttribute('aria-label');choose(key,['people','episodes','hours','cameras'].includes(key)?Number(button.dataset.value):button.dataset.value);const match=[...document.querySelectorAll('[data-key]')].find(el=>label?el.getAttribute('aria-label')===label:el.dataset.key===key&&el.dataset.value===button.dataset.value);match?.focus({preventScroll:true})});
 document.querySelectorAll('[data-extra]').forEach(button=>button.onclick=()=>{const id=button.dataset.extra;choose('extras',state.extras.includes(id)?state.extras.filter(value=>value!==id):[...state.extras,id]);document.querySelector(`[data-extra="${id}"]`)?.focus({preventScroll:true})});
 document.querySelectorAll('[data-section]').forEach(button=>button.onclick=()=>{state.section=button.dataset.section;summaryOpen=false;render();focusTask()});
 if($('.advanced'))$('.advanced').ontoggle=event=>{detailsOpen=event.target.open};
 for(const id of['date','location'])if($('#'+id))$('#'+id).onchange=event=>{choose(id,event.target.value);$('#'+id)?.focus({preventScroll:true})};
 for(const id of['name','email'])if($('#'+id))$('#'+id).oninput=event=>{state[id]=event.target.value;persist()};
 if($('#contact'))$('#contact').onsubmit=event=>{event.preventDefault();next()};
 document.querySelectorAll('#reset').forEach(button=>button.onclick=()=>{if(confirm('Clear your draft and start again?')){state=initial();priceChange='';detailsOpen=false;navigate('explore')}});
 if($('#edit-plan'))$('#edit-plan').onclick=()=>{state.complete=false;state.section='shoot';render()};
 if($('#download'))$('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({notice:'Demo only. Not submitted. Illustrative pricing.',brief:state,estimate:priceLines(state),total:total(state)},null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='visionhaus-demo-brief.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 bindControls();
}
render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{/* App remains usable online. */});
